INSERT INTO `scenarios` (`id`, `title`, `description`, `opening`, `ai_instructions`, `tags`, `builtin`) VALUES ('builtin-fantasy-waystation', 'Embers of the Waystation', 'The mountain road is closed by snow behind you and open to war ahead of you. A ruined waystation squats at the crossroads, its stable roof long burned, its well rumored to still hold water.', 'Dusk settles blue over the crossroads as you push open the waystation hanging door. Ash stirs on the cold hearth. Somewhere below the floorboards, water drips: the old well, still alive. Then you hear it — a boot scuffing on the stable-yard cinders, too deliberate to be the wind.', 'Narrate in second person, present tense. The world is low-fantasy: no fireballs, only rumors of old powers. Honor the traveler supplies — food, dry tinder, and daylight are scarce and tracked. Introduce one stranger at a time and give each a want and a secret. Foreshadow every threat before it strikes.', '["fantasy","adventure"]', 1);
INSERT INTO `scenarios` (`id`, `title`, `description`, `opening`, `ai_instructions`, `tags`, `builtin`) VALUES ('builtin-scifi-derelict', 'The Kestrel Silence', 'Your salvage crew has matched velocity with the Meridian Kestrel, a colony hauler silent for eleven years. The contract pays by recovered manifest — but the ship reactor is warm, and warm means awake.', 'Mag-locks clunk home and the umbilical sighs against the Kestrel airlock. Your helmet lamp sweeps a corridor of frost-bloomed storage pods, every one of them open, every one of them empty. Then the deck hums under your boots, and a voice from the ship own speakers says your name.', 'Hard sci-fi tone: vacuum, mass, and procedure matter. Track oxygen, power, and hull integrity; scarcity drives tension. The ship systems are alien in behavior but mechanical in nature — never supernatural. Reveal what happened to the crew in layers: evidence first, conclusions later.', '["sci-fi","mystery"]', 1);
INSERT INTO `scenarios` (`id`, `title`, `description`, `opening`, `ai_instructions`, `tags`, `builtin`) VALUES ('builtin-mystery-hollow-creek', 'Hollow Creek, 1974', 'Hollow Creek is a town of nine hundred people, one stoplight, and — as of last Tuesday — one missing paperboy. The county sheriff has called it a runaway. The boy bicycle says otherwise.', 'The bicycle leans against the grain elevator exactly where the morning freight would have hidden it from the road. The front wheel still spins when you touch it. Paper route bag folded. No footprints leading away, only toward. It has rained every night this week, and it did not rain last night.', 'Grounded 1970s small-town procedural. No forensics beyond fingerprints and legwork; the phone has a cord and the library closes at six. Every named resident has a routine — break one routine per scene to signal that something is wrong. The truth must be deducible from planted clues; never withhold the decisive detail.', '["mystery","1970s"]', 1);
